    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = f(n)
        if n > 1000000:  # To prevent infinite loop, we stop if the value exceeds a large number
            return False
    return n == 1

count = 0
for n in range(1, 101):
    if reaches_one(n):
        count += 1

